(function () {
  const input = document.querySelector(".search-input");
  const results = document.querySelector(".search-results");
  if (!input || !results) return;

  function escapeHtml(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function render(query) {
    const q = query.trim().toLowerCase();
    if (!q) {
      results.hidden = true;
      results.innerHTML = "";
      return;
    }
    const starts = [];
    const contains = [];
    for (const item of SEARCH_INDEX) {
      const i = item.title.toLowerCase().indexOf(q);
      if (i === -1) continue;
      (i === 0 ? starts : contains).push(item);
    }
    const matches = starts.concat(contains).slice(0, 15);
    results.innerHTML = matches.length
      ? matches.map((m) => '<a class="search-result-item" href="' + m.url + '">' + escapeHtml(m.title) + '<span class="search-result-domain">' + escapeHtml(m.domain) + "</span></a>").join("")
      : '<div class="search-no-results">No matches</div>';
    results.hidden = false;
  }

  input.addEventListener("input", function () { render(input.value); });
  input.addEventListener("focus", function () { if (input.value) render(input.value); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { results.hidden = true; input.blur(); }
    if (e.key === "Enter") { const first = results.querySelector("a"); if (first) first.click(); }
  });
  // Clears the field once a result is actually followed -- both a mouse
  // click and the Enter-key handler above end up dispatching a real click
  // on the result <a>, so this single listener covers both.
  results.addEventListener("click", function () {
    input.value = "";
    results.hidden = true;
    results.innerHTML = "";
  });
  document.addEventListener("click", function (e) {
    if (!e.target.closest(".navbar-search")) results.hidden = true;
  });
})();

// Light/dark toggle (top-right glyph button). The initial theme is already
// applied by the inline script right after <body> (see pageShell) -- before
// this file even loads -- so all that's left here is reacting to clicks.
// The domain switch (top-left logos) needs no dedicated handler of its own
// -- it's a real link now (see HOME_URLS in build-site.js), handled by the
// generic click listener above like any other nav link.
const THEME_STORAGE_KEY = "theme";
const themeToggle = document.querySelector(".theme-toggle");
if (themeToggle) {
  themeToggle.addEventListener("click", function () {
    const next = document.body.classList.contains("theme-dark") ? "light" : "dark";
    document.body.classList.remove("theme-light", "theme-dark");
    document.body.classList.add("theme-" + next);
    localStorage.setItem(THEME_STORAGE_KEY, next);
  });
}
